-- Run in the same database used by the backend.
-- Import the 18 former frontend articles; existing slugs are retained.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @AuthorId INT = (
    SELECT TOP (1) user_id FROM [User]
    WHERE system_role = 'admin' AND account_status = 'active'
    ORDER BY user_id
);
DECLARE @Articles TABLE (
    slug NVARCHAR(240), title NVARCHAR(220), summary NVARCHAR(MAX), body NVARCHAR(MAX),
    image NVARCHAR(MAX), category NVARCHAR(100), tags NVARCHAR(500), published_at DATETIME2(0), view_count INT
);
INSERT INTO @Articles (slug, title, summary, body, image, category, tags, published_at, view_count)
VALUES
(N'vietgap-la-gi-va-vi-sao-nong-ho-nen-ap-dung', N'VietGAP là gì và vì sao nông hộ nên áp dụng?', N'Tổng quan về tiêu chuẩn Thực hành nông nghiệp tốt tại Việt Nam (VietGAP), lợi ích cho nông hộ và thị trường tiêu thụ.', N'VietGAP (Vietnamese Good Agricultural Practices) là tập hợp các nguyên tắc, trình tự và thủ tục hướng dẫn sản xuất nhằm đảm bảo an toàn thực phẩm, truy xuất nguồn gốc, bảo vệ môi trường và sức khoẻ người lao động. Áp dụng VietGAP giúp nông hộ nâng cao uy tín sản phẩm, dễ dàng tiếp cận các kênh phân phối hiện đại như siêu thị, xuất khẩu, đồng thời giảm thiểu rủi ro về dư lượng hoá chất và dịch hại.', N'https://images.unsplash.com/photo-1500937386664-56d1dfef3854?auto=format&fit=crop&w=800&q=80', N'regulation', N'tổng quan, tiêu chuẩn, chứng nhận', N'2026-08-20', 1520),
(N'4-nhom-tieu-chi-bat-buoc-trong-chung-nhan-vietgap', N'4 nhóm tiêu chí bắt buộc trong chứng nhận VietGAP', N'Phân tích các nhóm tiêu chí: đánh giá vùng sản xuất, giống, quản lý đất - nước và ghi chép hồ sơ.', N'Bộ tiêu chí VietGAP được chia thành các nhóm chính: (1) đánh giá và lựa chọn vùng sản xuất phù hợp, không bị ô nhiễm; (2) quản lý giống và gốc ghép có nguồn gốc rõ ràng; (3) quản lý đất, giá thể và nguồn nước tưới; (4) ghi chép, lưu trữ hồ sơ phục vụ truy xuất nguồn gốc. Mỗi nhóm tiêu chí có các chỉ tiêu bắt buộc (A) và khuyến khích (B), nông hộ cần đạt 100% chỉ tiêu bắt buộc để được cấp chứng nhận.', N'https://images.unsplash.com/photo-1738598668890-5f4d28842df5?auto=format&fit=crop&w=800&q=80', N'regulation', N'tiêu chí, chứng nhận', N'2026-08-15', 1180),
(N'quy-trinh-dang-ky-va-cap-giay-chung-nhan-vietgap', N'Quy trình đăng ký và cấp giấy chứng nhận VietGAP', N'Các bước từ chuẩn bị hồ sơ, đánh giá nội bộ đến đăng ký với tổ chức chứng nhận.', N'Quy trình gồm: chuẩn bị hồ sơ vùng sản xuất, xây dựng quy trình sản xuất và mẫu biểu ghi chép, tổ chức đào tạo nội bộ, tự đánh giá theo checklist VietGAP, khắc phục các điểm chưa đạt, sau đó nộp hồ sơ đăng ký với tổ chức chứng nhận được chỉ định. Tổ chức chứng nhận sẽ cử chuyên gia đánh giá thực địa trước khi cấp giấy chứng nhận có hiệu lực tối đa 3 năm.', N'https://images.unsplash.com/photo-1727099079513-952d40de9d78?auto=format&fit=crop&w=800&q=80', N'regulation', N'quy trình, hồ sơ', N'2026-07-28', 860),
(N'danh-gia-va-lua-chon-vung-san-xuat-an-toan', N'Đánh giá và lựa chọn vùng sản xuất an toàn', N'Các yếu tố cần khảo sát: nguồn ô nhiễm, lịch sử canh tác và khoảng cách với khu công nghiệp.', N'Trước khi canh tác, cần khảo sát lịch sử sử dụng đất, khoảng cách tới khu công nghiệp, bãi rác, nghĩa trang hoặc nguồn nước thải chưa qua xử lý. Nếu nghi ngờ đất hoặc nước có nguy cơ ô nhiễm kim loại nặng, nên lấy mẫu phân tích tại phòng thí nghiệm được công nhận trước khi đưa vào sản xuất.', N'https://images.unsplash.com/photo-1697897400733-46e12551a012?auto=format&fit=crop&w=800&q=80', N'soil-water', N'vùng sản xuất, khảo sát', N'2026-08-02', 640),
(N'quan-ly-va-cai-tao-dat-trong-theo-huong-ben-vung', N'Quản lý và cải tạo đất trồng theo hướng bền vững', N'Luân canh, che phủ đất và bổ sung hữu cơ để duy trì độ phì nhiêu lâu dài.', N'Để duy trì độ phì nhiêu, nông hộ nên luân canh cây trồng, hạn chế cày xới quá mức, bổ sung phân hữu cơ hoai mục và che phủ đất bằng rơm rạ hoặc màng phủ sinh học. Định kỳ kiểm tra pH và hàm lượng dinh dưỡng trong đất để điều chỉnh lượng phân bón phù hợp, tránh bón thừa gây thoái hoá đất.', N'https://images.unsplash.com/photo-1586771107445-d3ca888129ff?auto=format&fit=crop&w=800&q=80', N'soil-water', N'đất trồng, canh tác bền vững', N'2026-06-30', 512),
(N'tieu-chuan-chat-luong-nuoc-tuoi-trong-vietgap', N'Tiêu chuẩn chất lượng nước tưới trong VietGAP', N'Ngưỡng cho phép về vi sinh và kim loại nặng trong nước tưới, tần suất kiểm nghiệm.', N'Nước tưới phải được kiểm nghiệm định kỳ (tối thiểu 1 lần/năm) để đảm bảo không vượt ngưỡng cho phép về E.coli, kim loại nặng và hoá chất tồn dư theo quy chuẩn QCVN hiện hành. Không sử dụng nước thải sinh hoạt hoặc công nghiệp chưa qua xử lý để tưới cho cây trồng.', N'https://images.unsplash.com/photo-1752775312083-1cefe2f93358?auto=format&fit=crop&w=800&q=80', N'soil-water', N'nước tưới, kiểm nghiệm', N'2026-05-18', 398),
(N'chon-giong-cay-trong-dat-chuan-vietgap', N'Chọn giống cây trồng đạt chuẩn VietGAP', N'Tiêu chí lựa chọn nguồn giống rõ ràng, khoẻ mạnh và phù hợp điều kiện canh tác.', N'Giống hoặc gốc ghép phải có nguồn gốc rõ ràng, được mua từ cơ sở cung ứng giống hợp pháp, có hồ sơ theo dõi lô giống. Nếu tự nhân giống, cần ghi chép đầy đủ nguồn gốc cây mẹ, thời gian nhân giống và kết quả kiểm tra sâu bệnh trước khi đưa vào sản xuất đại trà.', N'https://images.unsplash.com/photo-1781782411066-c68b1e5610bc?auto=format&fit=crop&w=800&q=80', N'seed-cultivation', N'giống cây trồng, nguồn gốc', N'2026-08-10', 705),
(N'ky-thuat-gieo-trong-va-mat-do-hop-ly-theo-mua-vu', N'Kỹ thuật gieo trồng và mật độ hợp lý theo mùa vụ', N'Bố trí mật độ, thời vụ và khoảng cách trồng để tối ưu năng suất, hạn chế sâu bệnh.', N'Mật độ gieo trồng cần dựa trên đặc tính giống, độ phì đất và điều kiện khí hậu từng vùng. Trồng quá dày làm tăng độ ẩm tán lá, tạo điều kiện cho nấm bệnh phát triển; trồng quá thưa lại lãng phí diện tích canh tác. Nên tham khảo lịch thời vụ khuyến cáo của cơ quan khuyến nông địa phương.', N'https://images.unsplash.com/photo-1773994788915-7fb0f462f223?auto=format&fit=crop&w=800&q=80', N'seed-cultivation', N'thời vụ, mật độ trồng', N'2026-04-22', 340),
(N'nguyen-tac-4-dung-khi-su-dung-thuoc-bao-ve-thuc-vat', N'Nguyên tắc "4 đúng" khi sử dụng thuốc bảo vệ thực vật', N'Đúng thuốc, đúng liều lượng, đúng lúc và đúng cách để đảm bảo an toàn và hiệu quả.', N'Nguyên tắc 4 đúng gồm: đúng thuốc (nằm trong danh mục được phép sử dụng), đúng liều lượng - nồng độ theo khuyến cáo trên nhãn, đúng thời điểm (tránh giai đoạn gần thu hoạch để đảm bảo thời gian cách ly), và đúng cách phun rải. Tuân thủ nguyên tắc này giúp giảm dư lượng thuốc trên nông sản và bảo vệ sức khoẻ người phun thuốc.', N'https://images.unsplash.com/photo-1625246333195-78d9c38ad449?auto=format&fit=crop&w=800&q=80', N'fertilizer-pesticide', N'thuốc BVTV, an toàn', N'2026-08-05', 990),
(N'thoi-gian-cach-ly-thuoc-bvtv-truoc-khi-thu-hoach', N'Thời gian cách ly thuốc BVTV trước khi thu hoạch', N'Cách tra cứu và tuân thủ thời gian cách ly để nông sản đạt ngưỡng dư lượng an toàn.', N'Mỗi loại thuốc bảo vệ thực vật có thời gian cách ly khác nhau, được ghi rõ trên nhãn sản phẩm. Nông hộ cần ghi chép ngày phun thuốc và tính toán ngày thu hoạch dự kiến để đảm bảo tuân thủ đúng thời gian cách ly, tránh thu hoạch sớm khi dư lượng thuốc còn vượt ngưỡng cho phép.', N'https://images.unsplash.com/photo-1595974482597-4b8da8879bc5?auto=format&fit=crop&w=800&q=80', N'fertilizer-pesticide', N'thời gian cách ly, dư lượng', N'2026-03-14', 455),
(N'su-dung-phan-bon-huu-co-va-vo-co-can-doi', N'Sử dụng phân bón hữu cơ và vô cơ cân đối', N'Kết hợp phân hữu cơ hoai mục với phân vô cơ theo nhu cầu dinh dưỡng của cây.', N'Việc kết hợp phân hữu cơ đã hoai mục với phân vô cơ theo đúng liều lượng giúp cải thiện cấu trúc đất, cung cấp dinh dưỡng cân đối và hạn chế ô nhiễm nguồn nước do rửa trôi phân bón. Không sử dụng phân chuồng tươi chưa qua ủ hoai để tránh lây nhiễm vi sinh vật gây hại.', N'https://images.unsplash.com/photo-1729009511263-329748943004?auto=format&fit=crop&w=800&q=80', N'fertilizer-pesticide', N'phân bón, dinh dưỡng', N'2026-02-27', 289),
(N'ky-thuat-thu-hoach-giam-ton-that-sau-thu-hoach', N'Kỹ thuật thu hoạch giảm tổn thất sau thu hoạch', N'Thời điểm thu hoạch, dụng cụ và cách xử lý sơ bộ để giữ chất lượng nông sản.', N'Thu hoạch đúng độ chín sinh lý, sử dụng dụng cụ sạch, sắc bén để hạn chế tổn thương cơ học trên nông sản. Sau thu hoạch, cần phân loại, loại bỏ sản phẩm hư hỏng và bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp để giảm thiểu hao hụt và giữ chất lượng trước khi vận chuyển.', N'https://images.unsplash.com/photo-1746014929708-fcb859fd3185?auto=format&fit=crop&w=800&q=80', N'harvest-post-harvest', N'thu hoạch, bảo quản', N'2026-07-19', 610),
(N've-sinh-dung-cu-va-khu-vuc-so-che-nong-san', N'Vệ sinh dụng cụ và khu vực sơ chế nông sản', N'Yêu cầu vệ sinh đối với dụng cụ chứa đựng, khu sơ chế để tránh lây nhiễm chéo.', N'Khu vực sơ chế, đóng gói cần được vệ sinh định kỳ, có khu vực riêng biệt tránh lây nhiễm chéo giữa sản phẩm và chất thải. Dụng cụ chứa đựng (sọt, thùng) nên làm từ vật liệu dễ vệ sinh, không sử dụng chung với dụng cụ đựng hoá chất hoặc phân bón.', N'https://images.unsplash.com/photo-1657288089316-c0350003ca49?auto=format&fit=crop&w=800&q=80', N'harvest-post-harvest', N'vệ sinh, sơ chế', N'2026-01-30', 275),
(N'he-thong-ghi-chep-nhat-ky-canh-tac-theo-vietgap', N'Hệ thống ghi chép nhật ký canh tác theo VietGAP', N'Các loại biểu mẫu cần lưu trữ: giống, phân bón, thuốc BVTV, thu hoạch và tiêu thụ.', N'Nông hộ cần duy trì nhật ký ghi chép đầy đủ: nguồn gốc giống, lịch sử sử dụng phân bón và thuốc BVTV (ngày, loại, liều lượng), ngày thu hoạch, sản lượng và nơi tiêu thụ. Hồ sơ này là căn cứ quan trọng để truy xuất nguồn gốc khi có yêu cầu kiểm tra hoặc khi xảy ra sự cố về an toàn thực phẩm.', N'https://images.unsplash.com/photo-1748742633127-941ebec208da?auto=format&fit=crop&w=800&q=80', N'record-traceability', N'ghi chép, nhật ký', N'2026-08-12', 830),
(N'ma-so-vung-trong-va-truy-xuat-nguon-goc-dien-tu', N'Mã số vùng trồng và truy xuất nguồn gốc điện tử', N'Vai trò của mã số vùng trồng và QR code trong việc minh bạch chuỗi cung ứng.', N'Mã số vùng trồng giúp cơ quan quản lý và người tiêu dùng xác định chính xác nguồn gốc xuất xứ của nông sản. Kết hợp với hệ thống QR code hoặc phần mềm nhật ký điện tử, nông hộ có thể minh bạch hoá toàn bộ quá trình canh tác, từ đó tăng độ tin cậy khi xuất khẩu hoặc bán vào kênh phân phối hiện đại.', N'https://images.unsplash.com/photo-1775681150283-04970adf1b98?auto=format&fit=crop&w=800&q=80', N'record-traceability', N'mã vùng trồng, QR code', N'2026-06-08', 470),
(N'dao-tao-va-trang-bi-bao-ho-cho-nguoi-lao-dong', N'Đào tạo và trang bị bảo hộ cho người lao động', N'Yêu cầu tập huấn định kỳ, sử dụng đồ bảo hộ khi tiếp xúc hoá chất nông nghiệp.', N'Người lao động trực tiếp tham gia sản xuất cần được tập huấn định kỳ về kỹ thuật canh tác an toàn, cách sử dụng và bảo quản hoá chất, cũng như sơ cứu khi xảy ra sự cố. Khi pha chế hoặc phun thuốc BVTV, bắt buộc trang bị đầy đủ đồ bảo hộ như khẩu trang, găng tay, kính bảo hộ và quần áo dài tay.', N'https://images.unsplash.com/photo-1781785186628-e1a04569776d?auto=format&fit=crop&w=800&q=80', N'training-certification', N'đào tạo, an toàn lao động', N'2026-07-02', 560),
(N'danh-gia-noi-bo-truoc-khi-dang-ky-chung-nhan', N'Đánh giá nội bộ trước khi đăng ký chứng nhận', N'Cách xây dựng checklist tự đánh giá và khắc phục điểm chưa đạt trước khi mời đánh giá.', N'Trước khi mời tổ chức chứng nhận đánh giá chính thức, nông hộ nên tự tổ chức đánh giá nội bộ dựa trên checklist đầy đủ các chỉ tiêu VietGAP. Việc này giúp phát hiện sớm các điểm chưa đạt để có thời gian khắc phục, tránh mất chi phí và thời gian khi đánh giá chính thức không đạt yêu cầu.', N'https://images.unsplash.com/photo-1738244969496-eeabfacec172?auto=format&fit=crop&w=800&q=80', N'training-certification', N'đánh giá nội bộ, checklist', N'2026-05-25', 415),
(N'quan-ly-va-xu-ly-chat-thai-nong-nghiep-dung-cach', N'Quản lý và xử lý chất thải nông nghiệp đúng cách', N'Phân loại bao bì thuốc BVTV, chất thải hữu cơ và nơi thu gom theo quy định.', N'Bao bì, chai lọ đựng thuốc BVTV sau sử dụng phải được thu gom vào bể chứa chuyên dụng, không vứt bừa bãi ra kênh mương hoặc đồng ruộng. Chất thải hữu cơ như cành lá, phụ phẩm cây trồng nên được ủ compost để tái sử dụng làm phân bón, góp phần giảm thiểu ô nhiễm môi trường xung quanh khu vực canh tác.', N'https://images.unsplash.com/photo-1742071853823-f9f87d9f3894?auto=format&fit=crop&w=800&q=80', N'soil-water', N'chất thải, môi trường', N'2026-04-05', 322);

INSERT INTO [KnowledgeArticle] (created_by, title, slug, summary, body, cover_image_url,
    category, tags, view_count, article_status, published_at)
SELECT @AuthorId, a.title, a.slug, a.summary, a.body, a.image,
    a.category, a.tags, a.view_count, 'published', a.published_at
FROM @Articles a
WHERE NOT EXISTS (SELECT 1 FROM [KnowledgeArticle] k WITH (UPDLOCK, HOLDLOCK) WHERE k.slug = a.slug);
DECLARE @Inserted INT = @@ROWCOUNT;
SELECT @Inserted AS inserted_articles,
    (SELECT COUNT(*) FROM [KnowledgeArticle] k JOIN @Articles a ON a.slug = k.slug) AS matching_articles;
COMMIT TRANSACTION;
